#!/usr/bin/env bash# Function to generate completions for `ollama run`function _ollama_completions() {    # Check if the current command is "ollama run"    if [[ "${COMP_WORDS[0]}" != "ollama" || "${COMP_WORDS[1]}" != "run" ]]; then        COMPREPLY=()        return    fi    local cur prev words cword    _get_comp_words_by_ref -n : cur prev words cword    __ltrim_colon_completions "$cur"    # Check if ollama command is available    if ! command -v ollama &>/dev/null; then        COMPREPLY=()        return    fi    # Get list of models from ollama (skip possible header)    local models    models=$(ollama list 2>/dev/null | awk 'NR>1 {print $1}' || true)    # Generate completions based on the current prefix    if [[ -n "$cur" ]]; then        COMPREPLY=($(compgen -W "$(echo "$models" | tr '\n' ' ')" -- "$cur"))    else        COMPREPLY=($(echo "$models" | tr '\n' ' ' | sort -u))    fi}# Register the completion function for `ollama run`complete -F _ollama_completions ollama